// SPDM_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module SPDM_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [7:0] c_ct_exp,
  input logic [1:0] c_pset,
  input logic  c_kg_sel,
  input logic [31:0] c_asym_id,
  input logic [14:0] c_cc_len,
  input logic [3:0] c_m_en,
  input logic [3:0] c_m_tcb,
  input logic [31:0] c_m_type,
  input logic [31:0] c_st_data,
  input logic [11:0] c_st_addr,
  input logic  c_st_sel,
  input logic [255:0] c_seed,
  input logic  c_kg_start,
  input logic  c_pk_open,
  input logic  c_clr,
  input logic [31:0] c_pk_data,
  input logic  c_pk_last,
  input logic [31:0] c_rn_data,
  input logic  c_busy,
  input logic [1:0] c_conn,
  input logic  c_key_ok,
  input logic [1:0] c_key_pset,
  input logic [7:0] c_err_code,
  input logic  c_st_we,
  input logic  c_pk_valid,
  input logic  c_pk_ready,
  input logic  c_rn_valid,
  input logic  c_rn_ready,
  input logic  c_rsp_done,
  input logic  c_rsp_err,
  input logic  c_kg_done,
  input logic  c_cmd_err
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 25;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:24];          // model of every stored word
  logic [6:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;
  logic m_state_STORE;          // full / valid pulse / available
  logic m_state_PK;          // full / valid pulse / available
  logic m_state_RN;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_rsp_done) m_set[0] = 1'b1;
    if (c_rsp_err) m_set[1] = 1'b1;
    if (c_kg_done) m_set[2] = 1'b1;
    if (c_cmd_err) m_set[3] = 1'b1;
    if (c_pk_valid && !m_state_PK) m_set[4] = 1'b1;
    if (c_pk_valid && m_state_PK && (m_rd && m_map && m_idx == 22)) m_set[4] = 1'b1;
    if (m_state_RN && c_rn_ready) m_set[5] = 1'b1;
    if (m_wr && m_map && (m_idx == 23) && m_state_RN) m_set[6] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_w[16] <= 32'h0;
      m_w[17] <= 32'h0;
      m_w[18] <= 32'h0;
      m_w[19] <= 32'h0;
      m_w[20] <= 32'h0;
      m_w[21] <= 32'h0;
      m_w[22] <= 32'h0;
      m_w[23] <= 32'h0;
      m_w[24] <= 32'h0;
      m_pulse_CMD <= 0;
      m_state_STORE <= 0;
      m_state_PK <= 0;
      m_state_RN <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h7F;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h7FF;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'h7FFF;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFF;
      if (m_wr && m_map && m_idx == 9) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 12) m_w[12] <= ((m_w[12] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 13) m_w[13] <= ((m_w[13] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 14) m_w[14] <= ((m_w[14] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 15) m_w[15] <= ((m_w[15] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 16) m_w[16] <= ((m_w[16] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 17) m_w[17] <= ((m_w[17] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 18) m_w[18] <= ((m_w[18] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 19) m_w[19] <= ((m_w[19] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 20) ? PWDATA & m_be & 32'h7 : 0;
      if (m_wr && m_map && m_idx == 10) m_w[10] <= ((m_w[10] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 11) m_w[11] <= ((m_w[11] & ~m_be) | (PWDATA & m_be)) & 32'h1FFF;
      m_state_STORE <= m_wr && m_map && m_idx == 11;
      if (c_pk_valid && (!m_state_PK || (m_rd && m_map && m_idx == 22))) begin
        m_w[21] <= (32'(c_pk_data[31:0]) << 0);
        m_w[22] <= (32'(c_pk_last) << 0);
        m_state_PK <= 1;
      end else if ((m_rd && m_map && m_idx == 22)) m_state_PK <= 0;
      if (m_wr && m_map && m_idx == 23 && !m_state_RN) m_w[23] <= ((m_w[23] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 23 && !m_state_RN) m_state_RN <= 1;
      if (m_state_RN && c_rn_ready) m_state_RN <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h53640100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_RN, m_state_PK});
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return m_w[11];
      12: return 0;
      13: return 0;
      14: return 0;
      15: return 0;
      16: return 0;
      17: return 0;
      18: return 0;
      19: return 0;
      20: return 0;
      21: return m_w[21];
      22: return m_w[22];
      23: return m_w[23];
      24: return (32'(c_busy) << 0) | (32'(c_conn) << 1) | (32'(c_key_ok) << 3) | (32'(c_key_pset) << 4) | (32'(c_err_code) << 6);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][6:0] & m_w[2][6:0]))
  `SVA_INV(a_core_ct_exp, c_ct_exp == m_w[5][7:0])
  `SVA_INV(a_core_pset, c_pset == m_w[5][9:8])
  `SVA_INV(a_core_kg_sel, c_kg_sel == m_w[5][10:10])
  `SVA_INV(a_core_asym_id, c_asym_id == m_w[6][31:0])
  `SVA_INV(a_core_cc_len, c_cc_len == m_w[7][14:0])
  `SVA_INV(a_core_m_en, c_m_en == m_w[8][3:0])
  `SVA_INV(a_core_m_tcb, c_m_tcb == m_w[8][7:4])
  `SVA_INV(a_core_m_type, c_m_type == m_w[9][31:0])
  `SVA_INV(a_core_st_data, c_st_data == m_w[10][31:0])
  `SVA_INV(a_core_st_addr, c_st_addr == m_w[11][11:0])
  `SVA_INV(a_core_st_sel, c_st_sel == m_w[11][12:12])
  `SVA_INV(a_core_seed_31_0, c_seed[31:0] == m_w[12][31:0])
  `SVA_INV(a_core_seed_63_32, c_seed[63:32] == m_w[13][31:0])
  `SVA_INV(a_core_seed_95_64, c_seed[95:64] == m_w[14][31:0])
  `SVA_INV(a_core_seed_127_96, c_seed[127:96] == m_w[15][31:0])
  `SVA_INV(a_core_seed_159_128, c_seed[159:128] == m_w[16][31:0])
  `SVA_INV(a_core_seed_191_160, c_seed[191:160] == m_w[17][31:0])
  `SVA_INV(a_core_seed_223_192, c_seed[223:192] == m_w[18][31:0])
  `SVA_INV(a_core_seed_255_224, c_seed[255:224] == m_w[19][31:0])
  `SVA_INV(a_core_kg_start, c_kg_start == m_pulse_CMD[0])
  `SVA_INV(a_core_pk_open, c_pk_open == m_pulse_CMD[1])
  `SVA_INV(a_core_clr, c_clr == m_pulse_CMD[2])
  `SVA_INV(a_core_rn_data, c_rn_data == m_w[23][31:0])
  `SVA_INV(a_core_st_we, c_st_we == m_state_STORE)
  `SVA_INV(a_core_pk_ready, c_pk_ready == (!m_state_PK || (m_rd && m_map && m_idx == 22)))
  `SVA_INV(a_core_rn_valid, c_rn_valid == m_state_RN)
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_ct_exp == 8'h0 && c_pset == 2'h0 && c_kg_sel == 1'h0 && c_asym_id == 32'h0 && c_cc_len == 15'h0 && c_m_en == 4'h0 && c_m_tcb == 4'h0 && c_m_type == 32'h0 && c_st_data == 32'h0 && c_st_addr == 12'h0 && c_st_sel == 1'h0 && c_seed[31:0] == 32'h0 && c_seed[63:32] == 32'h0 && c_seed[95:64] == 32'h0 && c_seed[127:96] == 32'h0 && c_seed[159:128] == 32'h0 && c_seed[191:160] == 32'h0 && c_seed[223:192] == 32'h0 && c_seed[255:224] == 32'h0 && c_kg_start == 1'h0 && c_pk_open == 1'h0 && c_clr == 1'h0 && c_rn_data == 32'h0 && !c_st_we && c_pk_ready && !c_rn_valid)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CFG, m_rd && m_map && m_idx == 5)
  `FC(wr_CFG, m_wr && m_map && m_idx == 5)
  `FC(rd_ASYM, m_rd && m_map && m_idx == 6)
  `FC(wr_ASYM, m_wr && m_map && m_idx == 6)
  `FC(rd_CCLEN, m_rd && m_map && m_idx == 7)
  `FC(wr_CCLEN, m_wr && m_map && m_idx == 7)
  `FC(rd_MEAS, m_rd && m_map && m_idx == 8)
  `FC(wr_MEAS, m_wr && m_map && m_idx == 8)
  `FC(rd_MTYPE, m_rd && m_map && m_idx == 9)
  `FC(wr_MTYPE, m_wr && m_map && m_idx == 9)
  `FC(rd_STORE0, m_rd && m_map && m_idx == 10)
  `FC(wr_STORE0, m_wr && m_map && m_idx == 10)
  `FC(rd_STORE1, m_rd && m_map && m_idx == 11)
  `FC(wr_STORE1, m_wr && m_map && m_idx == 11)
  `FC(rd_SEED0, m_rd && m_map && m_idx == 12)
  `FC(wr_SEED0, m_wr && m_map && m_idx == 12)
  `FC(rd_SEED1, m_rd && m_map && m_idx == 13)
  `FC(wr_SEED1, m_wr && m_map && m_idx == 13)
  `FC(rd_SEED2, m_rd && m_map && m_idx == 14)
  `FC(wr_SEED2, m_wr && m_map && m_idx == 14)
  `FC(rd_SEED3, m_rd && m_map && m_idx == 15)
  `FC(wr_SEED3, m_wr && m_map && m_idx == 15)
  `FC(rd_SEED4, m_rd && m_map && m_idx == 16)
  `FC(wr_SEED4, m_wr && m_map && m_idx == 16)
  `FC(rd_SEED5, m_rd && m_map && m_idx == 17)
  `FC(wr_SEED5, m_wr && m_map && m_idx == 17)
  `FC(rd_SEED6, m_rd && m_map && m_idx == 18)
  `FC(wr_SEED6, m_wr && m_map && m_idx == 18)
  `FC(rd_SEED7, m_rd && m_map && m_idx == 19)
  `FC(wr_SEED7, m_wr && m_map && m_idx == 19)
  `FC(rd_CMD, m_rd && m_map && m_idx == 20)
  `FC(wr_CMD, m_wr && m_map && m_idx == 20)
  `FC(rd_PK0, m_rd && m_map && m_idx == 21)
  `FC(wr_PK0, m_wr && m_map && m_idx == 21)
  `FC(rd_PK1, m_rd && m_map && m_idx == 22)
  `FC(wr_PK1, m_wr && m_map && m_idx == 22)
  `FC(rd_RN, m_rd && m_map && m_idx == 23)
  `FC(wr_RN, m_wr && m_map && m_idx == 23)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 24)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 24)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_RSP_DONE_set, m_set[0])
  `FC(irq_RSP_DONE_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_RSP_DONE_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_RSP_DONE_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_RSP_ERR_set, m_set[1])
  `FC(irq_RSP_ERR_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_RSP_ERR_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_RSP_ERR_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_KG_DONE_set, m_set[2])
  `FC(irq_KG_DONE_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_KG_DONE_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_KG_DONE_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_CMD_ERR_set, m_set[3])
  `FC(irq_CMD_ERR_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_CMD_ERR_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_CMD_ERR_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_PK_AVAIL_set, m_set[4])
  `FC(irq_PK_AVAIL_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_PK_AVAIL_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_PK_AVAIL_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(irq_RN_DONE_set, m_set[5])
  `FC(irq_RN_DONE_cleared, m_w[1][5] && m_wr && m_map && m_idx == 1 && PWDATA[5] && PSTRB[0])
  `FC(irq_RN_DONE_masked, m_w[1][5] && !m_w[2][5])
  `FC(irq_RN_DONE_drives_pin, m_w[1][5] && m_w[2][5] && irq)
  `FC(irq_RN_OVF_set, m_set[6])
  `FC(irq_RN_OVF_cleared, m_w[1][6] && m_wr && m_map && m_idx == 1 && PWDATA[6] && PSTRB[0])
  `FC(irq_RN_OVF_masked, m_w[1][6] && !m_w[2][6])
  `FC(irq_RN_OVF_drives_pin, m_w[1][6] && m_w[2][6] && irq)
  `FC(cmd_kg_start, m_pulse_CMD[0])
  `FC(cmd_pk_open, m_pulse_CMD[1])
  `FC(cmd_clr, m_pulse_CMD[2])
  `FC(STORE_commit, m_state_STORE)
  `FC(PK_capture, c_pk_valid && !m_state_PK)
  `FC(PK_backpressure, c_pk_valid && m_state_PK && !(m_rd && m_map && m_idx == 22))
  `FC(PK_pop, m_rd && m_map && m_idx == 22 && m_state_PK)
  `FC(PK_read_empty, m_rd && m_map && m_idx == 22 && !m_state_PK)
  `FC(PK_pop_and_capture, c_pk_valid && m_state_PK && m_rd && m_map && m_idx == 22)
  `FC(RN_handshake, m_state_RN && c_rn_ready)
  `FC(RN_backpressure, m_state_RN && !c_rn_ready)
  `FC(RN_write_while_full, m_wr && m_map && m_idx == 23 && m_state_RN)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind SPDM_apb SPDM_apb_sva u_apb_sva (.*);
